python3 << 'PYEOF'
import os
import re
from collections import defaultdict

REPO = "/bench/repo"
MODULE = "github.com/usememos/memos"

# Data layer paths (store package + its subpackages + proto store definitions)
DATA_LAYER_PREFIXES = [
    "/bench/repo/store/",
    "/bench/repo/proto/store/",
    "/bench/repo/proto/gen/store/",
]

# Persistent entity types from Driver interface + migrations
ENTITY_TYPES = [
    "Attachment", "Memo", "MemoRelation", "InstanceSetting",
    "User", "UserSetting", "IdentityProvider", "Inbox",
    "Reaction", "MemoShare", "UserIdentity",
]

def is_data_layer(path):
    return any(path.startswith(p) for p in DATA_LAYER_PREFIXES)

def get_package(path):
    """Return Go package import path from file path."""
    rel = path.replace(REPO + "/", "")
    if rel.startswith("cmd/"):
        parts = rel.split("/")
        return MODULE + "/" + "/".join(parts[:2])  # cmd/memos
    # directory containing the file
    d = os.path.dirname(rel)
    return MODULE + "/" + d if d else MODULE

def get_local_package_name(path):
    """Read package declaration."""
    try:
        with open(path) as f:
            for line in f:
                m = re.match(r'^package\s+(\w+)', line)
                if m:
                    return m.group(1)
    except:
        pass
    return None

# Collect all go files outside data layer
external_files = []
for root, dirs, files in os.walk(REPO):
    # skip .git
    if '.git' in root.split('/'):
        continue
    for fn in files:
        if fn.endswith('.go'):
            path = os.path.join(root, fn)
            if not is_data_layer(path):
                external_files.append(path)

# For each entity, find files referencing store.Entity or *store.Entity etc.
entity_packages = {e: set() for e in ENTITY_TYPES}
entity_files = {e: set() for e in ENTITY_TYPES}

patterns = {}
for e in ENTITY_TYPES:
    # Match store.Entity, *store.Entity, []*store.Entity, store.FindEntity, etc.
    patterns[e] = re.compile(
        r'\bstore\.(?:Find|Update|Delete|Create)?' + re.escape(e) + r'\b|\[\]\*store\.' + re.escape(e) + r'\b|\*store\.' + re.escape(e) + r'\b|\bstore\.' + re.escape(e) + r'\b'
    )

for path in external_files:
    try:
        content = open(path).read()
    except:
        continue
    pkg = get_package(path)
    for e, pat in patterns.items():
        if pat.search(content):
            entity_packages[e].add(pkg)
            entity_files[e].add(path)

# Also check proto entity references (storepb alias)
proto_aliases = ['storepb', 'storev1pb']  # common aliases
proto_entities = [
    "Attachment", "IdentityProvider", "Inbox", "InstanceSetting", 
    "Memo", "UserSetting", "InboxMessage"
]

for path in external_files:
    try:
        content = open(path).read()
    except:
        continue
    if 'proto/gen/store' not in content and 'storepb' not in content:
        continue
    pkg = get_package(path)

print("=== Entity type references via store.* (external packages) ===")
ranked = sorted(ENTITY_TYPES, key=lambda e: len(entity_packages[e]), reverse=True)
for e in ranked:
    pkgs = sorted(entity_packages[e])
    print(f"{e}: {len(pkgs)} packages")
    for p in pkgs[:8]:
        print(f"  {p}")
    if len(pkgs) > 8:
        print(f"  ... +{len(pkgs)-8} more")

print("\n=== Top entity sample files ===")
for e in ranked[:3]:
    print(f"\n{e}:")
    for f in sorted(entity_files[e])[:5]:
        print(f"  {f.replace(REPO+'/', '')}")

PYEOF

