perl -e '
use strict;
use warnings;
use File::Find;

my $REPO = "/bench/repo";
my $MODULE = "github.com/usememos/memos";

my @DATA_PREFIXES = (
    "$REPO/store/",
    "$REPO/proto/store/",
    "$REPO/proto/gen/store/",
);

my @ENTITIES = qw(
    Attachment Memo MemoRelation InstanceSetting
    User UserSetting IdentityProvider Inbox
    Reaction MemoShare UserIdentity
);

sub is_data_layer {
    my ($path) = @_;
    for my $p (@DATA_PREFIXES) {
        return 1 if index($path, $p) == 0;
    }
    return 0;
}

sub get_package {
    my ($path) = @_;
    my $rel = $path;
    $rel =~ s/^\Q$REPO\E\///;
